-- Bob's Used Books Classic - PostgreSQL 16 schema + seed data.
-- Per-engine translation of bobs-used-bookstore-classic-db.sql (SQL Server), generated by the
-- dual-db-port run against commit 7e3dc2f9. The SQL Server script is unchanged and remains
-- authoritative for SQL Server deployments.
--
-- Mapping decisions (identifier_style = preserve):
--   * Identifiers keep PascalCase and are double-quoted to match the EF6 model.
--   * nvarchar(max) -> text, nvarchar(450) -> varchar(450)
--   * datetime      -> timestamp (without time zone; application stores UTC values)
--   * decimal(18,2) -> numeric(18,2)
--   * bit           -> boolean
--   * int IDENTITY  -> GENERATED BY DEFAULT AS IDENTITY (explicit seed ids allowed)
--   * RowVersion (rowversion) is NOT created: PostgreSQL exposes the auto-updating system
--     column xmin instead; the EF6 PostgreSQL path does not map the concurrency token
--     (see DUAL_DB_PORT_REPORT.md section 8).
--   * __MigrationHistory is omitted: the original script's model blob embeds a SQL Server
--     SSDL and cannot be translated; EF6 creates and maintains its own history table when
--     the database initializer runs.
--   * SQL Server database-level options (compatibility level, full text, broker, filestream,
--     query store, recovery model) have no PostgreSQL equivalent and are omitted.

BEGIN;

CREATE TABLE "Address" (
    "Id"           integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "AddressLine1" text NULL,
    "AddressLine2" text NULL,
    "City"         text NULL,
    "State"        text NULL,
    "Country"      text NULL,
    "ZipCode"      text NULL,
    "CustomerId"   integer NOT NULL,
    "IsActive"     boolean NOT NULL,
    "CreatedBy"    text NULL,
    "CreatedOn"    timestamp NOT NULL,
    "UpdatedOn"    timestamp NOT NULL,
    CONSTRAINT "PK_Address" PRIMARY KEY ("Id")
);

CREATE TABLE "Book" (
    "Id"           integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Name"         text NULL,
    "Author"       text NULL,
    "Year"         integer NULL,
    "ISBN"         text NULL,
    "PublisherId"  integer NOT NULL,
    "BookTypeId"   integer NOT NULL,
    "GenreId"      integer NOT NULL,
    "ConditionId"  integer NOT NULL,
    "CoverImageUrl" text NULL,
    "Summary"      text NULL,
    "Price"        numeric(18, 2) NOT NULL,
    "Quantity"     integer NOT NULL,
    "CreatedBy"    text NULL,
    "CreatedOn"    timestamp NOT NULL,
    "UpdatedOn"    timestamp NOT NULL,
    CONSTRAINT "PK_Book" PRIMARY KEY ("Id")
);

CREATE TABLE "Customer" (
    "Id"          integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Sub"         varchar(450) NULL,
    "Username"    text NULL,
    "FirstName"   text NULL,
    "LastName"    text NULL,
    "Email"       text NULL,
    "DateOfBirth" timestamp NULL,
    "Phone"       text NULL,
    "CreatedBy"   text NULL,
    "CreatedOn"   timestamp NOT NULL,
    "UpdatedOn"   timestamp NOT NULL,
    CONSTRAINT "PK_Customer" PRIMARY KEY ("Id")
);

CREATE TABLE "Offer" (
    "Id"          integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Author"      text NULL,
    "ISBN"        text NULL,
    "BookName"    text NULL,
    "FrontUrl"    text NULL,
    "GenreId"     integer NOT NULL,
    "ConditionId" integer NOT NULL,
    "PublisherId" integer NOT NULL,
    "BookTypeId"  integer NOT NULL,
    "Summary"     text NULL,
    "OfferStatus" integer NOT NULL,
    "Comment"     text NULL,
    "CustomerId"  integer NOT NULL,
    "BookPrice"   numeric(18, 2) NOT NULL,
    "CreatedBy"   text NULL,
    "CreatedOn"   timestamp NOT NULL,
    "UpdatedOn"   timestamp NOT NULL,
    CONSTRAINT "PK_Offer" PRIMARY KEY ("Id")
);

CREATE TABLE "Order" (
    "Id"           integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CustomerId"   integer NOT NULL,
    "AddressId"    integer NOT NULL,
    "DeliveryDate" timestamp NOT NULL,
    "OrderStatus"  integer NOT NULL,
    "CreatedBy"    text NULL,
    "CreatedOn"    timestamp NOT NULL,
    "UpdatedOn"    timestamp NOT NULL,
    CONSTRAINT "PK_Order" PRIMARY KEY ("Id")
);

CREATE TABLE "OrderItem" (
    "Id"        integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "OrderId"   integer NOT NULL,
    "BookId"    integer NOT NULL,
    "Quantity"  integer NOT NULL,
    "CreatedBy" text NULL,
    "CreatedOn" timestamp NOT NULL,
    "UpdatedOn" timestamp NOT NULL,
    CONSTRAINT "PK_OrderItem" PRIMARY KEY ("Id")
);

CREATE TABLE "ReferenceData" (
    "Id"        integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "DataType"  integer NOT NULL,
    "Text"      text NULL,
    "CreatedBy" text NULL,
    "CreatedOn" timestamp NOT NULL,
    "UpdatedOn" timestamp NOT NULL,
    CONSTRAINT "PK_ReferenceData" PRIMARY KEY ("Id")
);

CREATE TABLE "ShoppingCart" (
    "Id"            integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CorrelationId" text NULL,
    "CreatedBy"     text NULL,
    "CreatedOn"     timestamp NOT NULL,
    "UpdatedOn"     timestamp NOT NULL,
    CONSTRAINT "PK_ShoppingCart" PRIMARY KEY ("Id")
);

CREATE TABLE "ShoppingCartItem" (
    "Id"            integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ShoppingCartId" integer NOT NULL,
    "BookId"        integer NOT NULL,
    "Quantity"      integer NOT NULL,
    "WantToBuy"     boolean NOT NULL,
    "CreatedBy"     text NULL,
    "CreatedOn"     timestamp NOT NULL,
    "UpdatedOn"     timestamp NOT NULL,
    CONSTRAINT "PK_ShoppingCartItem" PRIMARY KEY ("Id", "ShoppingCartId")
);

-- Seed data (mirrors the SQL Server script; identity override is permitted by
