-- Re-sync identity sequences above the seeded ids (runbook: required after any
-- explicit-id seed insert so the next application-generated id does not collide).
SELECT setval(pg_get_serial_sequence('"Book"', 'Id'), (SELECT MAX("Id") FROM "Book"));
SELECT setval(pg_get_serial_sequence('"ReferenceData"', 'Id'), (SELECT MAX("Id") FROM "ReferenceData"));

-- Indexes (same shapes and names as the SQL Server script, without clustered/storage options).

CREATE INDEX "IX_CustomerId" ON "Address" ("CustomerId");

CREATE INDEX "IX_BookTypeId" ON "Book" ("BookTypeId");
CREATE INDEX "IX_ConditionId" ON "Book" ("ConditionId");
CREATE INDEX "IX_GenreId" ON "Book" ("GenreId");
CREATE INDEX "IX_PublisherId" ON "Book" ("PublisherId");

CREATE UNIQUE INDEX "IX_Sub" ON "Customer" ("Sub");

CREATE INDEX "IX_BookTypeId" ON "Offer" ("BookTypeId");
CREATE INDEX "IX_ConditionId" ON "Offer" ("ConditionId");
CREATE INDEX "IX_CustomerId" ON "Offer" ("CustomerId");
CREATE INDEX "IX_GenreId" ON "Offer" ("GenreId");
CREATE INDEX "IX_PublisherId" ON "Offer" ("PublisherId");

CREATE INDEX "IX_AddressId" ON "Order" ("AddressId");
CREATE INDEX "IX_CustomerId" ON "Order" ("CustomerId");

CREATE INDEX "IX_BookId" ON "OrderItem" ("BookId");
CREATE INDEX "IX_OrderId" ON "OrderItem" ("OrderId");

CREATE INDEX "IX_BookId" ON "ShoppingCartItem" ("BookId");
CREATE INDEX "IX_ShoppingCartId" ON "ShoppingCartItem" ("ShoppingCartId");

-- Foreign keys (same delete rules as the SQL Server script).

ALTER TABLE "Address" ADD CONSTRAINT "FK_Address_Customer_CustomerId" FOREIGN KEY ("CustomerId")
