ALTER TABLE "Order" ADD CONSTRAINT "FK_Order_Customer_CustomerId" FOREIGN KEY ("CustomerId")
    REFERENCES "Customer" ("Id");

ALTER TABLE "OrderItem" ADD CONSTRAINT "FK_OrderItem_Book_BookId" FOREIGN KEY ("BookId")
